CREATE FUNCTION recovery_inventory_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.id,NEW.maker_id,NEW.fingerprint,NEW.content,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.maker_id,OLD.fingerprint,OLD.content,OLD.created_at) THEN RAISE EXCEPTION 'Recovery inventory identity is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER recovery_inventory_identity BEFORE UPDATE ON recovery_inventory FOR EACH ROW EXECUTE FUNCTION recovery_inventory_identity_guard();
CREATE FUNCTION purge_receipt_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.id,NEW.merchant_id,NEW.maker_id,NEW.inventory,NEW.fingerprint,NEW.backup_inventory,NEW.provider_hash,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.merchant_id,OLD.maker_id,OLD.inventory,OLD.fingerprint,OLD.backup_inventory,OLD.provider_hash,OLD.created_at) THEN RAISE EXCEPTION 'Purge receipt identity is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER purge_receipt_identity BEFORE UPDATE ON purge_receipt FOR EACH ROW EXECUTE FUNCTION purge_receipt_identity_guard();
INSERT INTO guard_registry SELECT tgname,md5(pg_get_triggerdef(oid)||pg_get_functiondef(tgfoid)) FROM pg_trigger WHERE tgname IN('recovery_inventory_identity','purge_receipt_identity');
